"""ARENA u04 的 10 道测验（沿用旧版）"""
from unitlib import Q
QUIZ = [
  Q('一个 2×2 矩阵的行列式是 3，这个变换对图形的面积做了什么？', ['面积变成原来的 3 倍', '面积不变', '面积变成原来的 1/3', '面积增加 3 个单位'], 0, '行列式就是面积的**缩放倍数**，所有区域都放大 3 倍。'),
  Q('$\\det\\begin{bmatrix} 2 & 1 \\\\ 4 & 3 \\end{bmatrix}$ 等于？', ['10', '5', '2', '-2'], 2, '$ad - bc = 2 \\times 3 - 1 \\times 4 = 2$。'),
  Q('行列式为负数说明什么？', ['变换不是线性的', '空间的定向被翻转了', '矩阵不可逆', '面积变小了'], 1, '负号表示定向翻转（像把纸翻面），绝对值仍然是缩放倍数。只要不为 0，矩阵就可逆。'),
  Q('矩阵 $A$ 可逆的充要条件是？', ['$A$ 的所有元素都不为 0', '$A$ 是对称矩阵', '$\\text{tr}(A) \\neq 0$', '$\\det(A) \\neq 0$'], 3, '行列式不为 0 ⇔ 空间没有被压扁 ⇔ 变换可以倒回去。元素里有 0 的矩阵照样可以可逆（比如单位矩阵）。'),
  Q('矩阵的 **秩 (rank)** 描述的是？', ['矩阵元素的个数', '矩阵的行数', '列空间的维数，即输出能铺满几维', '对角线元素之和'], 2, '秩 = 列空间的维数。对角线之和是**迹**。'),
  Q('$A$ 是 $(10, 3)$，$B$ 是 $(3, 8)$。$AB$ 的秩**最大**是多少？', ['3', '8', '10', '24'], 0, '$\\text{rank}(AB) \\le \\min(\\text{rank}(A), \\text{rank}(B)) \\le \\min(10, 3, 8) = 3$。虽然 $AB$ 是 10×8 的大矩阵，秩最多是 3。'),
  Q('一个 5×5 矩阵的秩是 3，它的零空间是几维？', ['0', '3', '5', '2'], 3, '秩–零化度定理：列数 = 秩 + 零空间维数，所以零空间维数 = 5 − 3 = 2。'),
  Q('$(AB)^\\top$ 等于？', ['$A^\\top B^\\top$', '$B^\\top A^\\top$', '$AB$', '$BA$'], 1, '转置会把乘积的顺序反过来。从形状也能验证：只有 $B^\\top A^\\top$ 的形状能对上。'),
  Q('关于迹 (trace)，下面哪个说法**错误**？', ['$\\text{tr}(AB) = \\text{tr}(A)\\,\\text{tr}(B)$', '$\\text{tr}(A)$ 是对角线元素之和', '$\\text{tr}(AB) = \\text{tr}(BA)$', '$\\text{tr}(A + B) = \\text{tr}(A) + \\text{tr}(B)$'], 0, '迹是线性的、满足循环性 $\\text{tr}(AB) = \\text{tr}(BA)$，但**乘积的迹一般不等于迹的乘积**。例如 $A = B = \\begin{bmatrix}1&0\\\\0&-1\\end{bmatrix}$：$\\text{tr}(AB) = 2$，而 $\\text{tr}(A)\\text{tr}(B) = 0$。（「乘积等于乘积」的是行列式：$\\det(AB) = \\det A \\det B$。）'),
  Q('$\\det(A) = 2$，$\\det(B) = 5$，则 $\\det(AB)$ 等于？', ['7', '2.5', '10', '无法确定'], 2, '$\\det(AB) = \\det(A)\\det(B) = 10$：先放大 5 倍再放大 2 倍，总共放大 10 倍。'),
]
